'use strict';

// MODULES //

var isFunction = require( '@stdlib/assert/is-function' );
var isReadOnly = require( '@stdlib/ndarray/base/assert/is-read-only' );
var isArrayLikeObject = require( '@stdlib/assert/is-array-like-object' );
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var isndarrayLike = require( '@stdlib/assert/is-ndarray-like' );
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var isMultiSlice = require( '@stdlib/assert/is-multi-slice' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var MultiSlice = require( '@stdlib/slice/multi' );
var args2multislice = require( '@stdlib/slice/base/args2multislice' );
var slice = require( '@stdlib/ndarray/base/slice' );
var base = require( '@stdlib/ndarray/base/fill-by' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Fills an input ndarray view according to a callback function.
*
* @param {ndarray} x - input ndarray
* @param {...*} s - slice arguments
* @param {Options} [options] - options
* @param {boolean} [options.strict] - boolean indicating whether to enforce strict bounds checking
* @param {Function} clbk - callback function
* @param {*} [thisArg] - callback execution context
* @throws {TypeError} first argument must be an ndarray-like object
* @throws {TypeError} options argument must be an object
* @throws {TypeError} must provide valid options
* @throws {TypeError} callback argument must be a function
* @throws {Error} too many arguments
* @throws {Error} cannot write to a read-only ndarray
* @returns {ndarray} input ndarray
*
* @example
* var zeros = require( '@stdlib/ndarray/zeros' );
* var MultiSlice = require( '@stdlib/slice/multi' );
* var Slice = require( '@stdlib/slice/ctor' );
*
* function clbk() {
*     return 5.0;
* }
*
* var x = zeros( [ 3, 4 ], {
*     'dtype': 'float64'
* });
*
* // Define the fill region:
* var s0 = new Slice( 1, 3 );
* var s1 = new Slice( 2, 4 );
* var s = new MultiSlice( s0, s1 );
*
* var y = fillSliceBy( x, s, clbk );
* // returns <ndarray>[ [ 0, 0, 0, 0 ], [ 0, 0, 5, 5 ], [ 0, 0, 5, 5 ] ]
*
* var bool = ( y === x );
* // returns true
*/
function fillSliceBy() {
	var options;
	var flgOpts;
	var flgCtx;
	var nargs;
	var sArgs;
	var opts;
	var ctx;
	var cb;
	var ns;
	var S;
	var s;
	var i;
	var x;

	opts = {
		'strict': true
	};
	flgOpts = false;
	flgCtx = false;
	nargs = arguments.length;
	x = arguments[ 0 ];

	if ( !isndarrayLike( x ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an ndarray. Value: `%s`.', x ) );
	}
	if ( isReadOnly( x ) ) {
		throw new Error( 'invalid argument. Cannot write to a read-only array.' );
	}

	// Resolve function arguments:
	if ( isFunction( arguments[ nargs - 1 ] ) ) { // Case: fillSliceBy( x, ???, ???, clbk )
		cb = arguments[ nargs - 1 ];
		if ( isPlainObject( arguments[ nargs - 2 ] ) ) { // Case: fillSliceBy( x, ???, options, clbk )
			flgOpts = true;
			options = arguments[ nargs - 2 ];
			if ( nargs > 3 ) {
				s = arguments[ nargs - 3 ];
			}
		} else if ( nargs > 2 ) { // Case: fillSliceBy( x, s, clbk )
			s = arguments[ nargs - 2 ];
		}
	} else if ( isFunction( arguments[ nargs - 2 ] ) ) { // Case: fillSliceBy( x, ???, ???, clbk, thisArg )
		cb = arguments[ nargs -2 ];
		ctx = arguments[ nargs - 1 ];
		flgCtx = true;
		if ( isPlainObject( arguments[ nargs - 3 ] ) ) { // Case: fillSliceBy( x, ???, options, clbk, thisArg )
			flgOpts = true;
			options = arguments[ nargs - 3 ];
			s = arguments[ nargs - 4 ];
		} else { // Case: fillSliceBy( x, s, clbk, thisArg )
			s = arguments[ nargs - 3 ];
		}
	} else {
		throw new TypeError( 'invalid argument. Callback argument must be a function' );
	}

	// Resolve function options:
	if ( flgOpts ) {
		if ( hasOwnProp( options, 'strict' ) ) {
			if ( !isBoolean( options.strict ) ) {
				throw new TypeError( format( 'invalid option. `%s` option must be a boolean. Option: `%s`.', 'strict', options.strict ) );
			}
			opts.strict = options.strict;
		}
	}

	// Resolve slice:
	if ( isMultiSlice( s ) ) {
		S = s;
		if ( nargs > 5 ) {
			throw new Error( 'invalid invocation. Too many arguments.' );
		}
	} else {
		if ( isArrayLikeObject( s ) ) {
			sArgs = s;
			if ( nargs > 5 ) {
				throw new Error( 'invalid invocation. Too many arguments.' );
			}
		} else {
			sArgs = [];
			ns = 0;
			if ( flgCtx && flgOpts ) {
				ns = nargs - 3;
			} else if ( flgCtx && !flgOpts ) {
				ns = nargs - 2;
			} else if ( !flgCtx && flgOpts ) {
				ns = nargs - 2;
			} else {
				ns = nargs - 1;
			}
			for ( i = 1; i < ns; i++ ) {
				sArgs.push( arguments[ i ] );
			}
		}
		try {
			S = args2multislice( sArgs );
		} catch ( err ) { // eslint-disable-line no-unused-vars
			// Search for the first offending value...
			for ( i = 0; i < sArgs.length; i++ ) {
				try {
					new MultiSlice( sArgs[ i ] ); // eslint-disable-line no-new
				} catch ( err ) { // eslint-disable-line no-unused-vars
					throw new TypeError( format( 'invalid argument. Slice arguments must be either a Slice, integer, null, or undefined. Value: `%s`.', String( sArgs[ i ] ) ) );
				}
			}
		}
	}
	base( slice( x, S, opts.strict, true ), cb, ctx );
	return x;
}


// EXPORTS //

module.exports = fillSliceBy;
